import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long k = nextLong();
        long[] v = new long[n];
        for (int i = 0; i < n; i++) v[i] = nextLong();
        // compress values so the frequency table is a plain array
        long[] s = v.clone();
        Arrays.sort(s);
        int u = 0;
        for (int i = 0; i < n; i++) if (i == 0 || s[i] != s[i - 1]) s[u++] = s[i];
        int[] id = new int[n], freq = new int[u];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(s, 0, u, v[i]);
        long pairs = 0, answer = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            if (++freq[id[right]] % 2 == 0) pairs++;
            while (pairs >= k) {
                answer += n - right;
                if (--freq[id[left++]] % 2 == 1) pairs--;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, k := next(), next()
	v := make([]int, n)
	for i := range v {
		v[i] = next()
	}
	// compress values so the frequency table is a plain slice
	s := append([]int(nil), v...)
	sort.Ints(s)
	u := 0
	for i := range s {
		if i == 0 || s[i] != s[i-1] {
			s[u] = s[i]
			u++
		}
	}
	s = s[:u]
	id := make([]int, n)
	for i, x := range v {
		id[i] = sort.SearchInts(s, x)
	}
	freq := make([]int, u)
	pairs, answer, left := 0, 0, 0
	for right := 0; right < n; right++ {
		freq[id[right]]++
		if freq[id[right]]%2 == 0 {
			pairs++
		}
		for pairs >= k {
			answer += n - right
			freq[id[left]]--
			if freq[id[left]]%2 == 1 {
				pairs--
			}
			left++
		}
	}
	fmt.Println(answer)
}
